sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

	var requestBody = request.body.data;
	var incidentSysId = requestBody.incident_sys_id;
	var workNote = requestBody.work_note;

	if (!incidentSysId || !workNote) {
		response.setStatus(400);
		return { status: "error", message: "Missing required fields: incident_sys_id or work_note" };
	}

	var importGR = new GlideRecord('x_xurre_imr_u_import_work_note');
	importGR.initialize();
	importGR.setValue('operation', 'create_work_note');
	importGR.setValue('incident_sys_id', incidentSysId);
	importGR.setValue('work_note', workNote);
	var importSysId = importGR.insert();

	if (!importGR.get(importSysId)) {
		response.setStatus(400);
		return { status: "error", message: "Import record not found after insert." };
	}
	var resultStatus = importGR.getValue('result_status');
	var resultMessage = importGR.getValue('result_message');
	var noteSysId = importGR.getValue('result_sys_id');

	if (resultStatus !== 'success') {
		response.setStatus(400);
		return { status: "error", message: resultMessage };
	}

	response.setStatus(200);
	return {
		status: "success",
		message: "Work note added successfully",
		sys_id: noteSysId
	};
})(request, response);
